/* Contract tests for the image module: Radiance HDR decode, format detection,
 * and the capability table. Oracle is assert-style CK counters; no stdout
 * noise on success. */
#include "zcsr/image.h"

#include <stdio.h>
#include <string.h>

static int fails = 0;
#define CK(label, cond) do { if (!(cond)) { printf("FAIL: %s\n", label); fails++; } } while (0)

/* 2x2 Radiance RGBE, non-RLE: black / red 1.0, green 1.0 / white 4.0.
 * Generated by modules/image sample generator (see delivery notes). */
static const unsigned char HDR_2x2[] = {
    0x23, 0x3f, 0x52, 0x41, 0x44, 0x49, 0x41, 0x4e, 0x43, 0x45, 0x0a, 0x46, 0x4f, 0x52, 0x4d, 0x41,
    0x54, 0x3d, 0x33, 0x32, 0x2d, 0x62, 0x69, 0x74, 0x5f, 0x72, 0x6c, 0x65, 0x5f, 0x72, 0x67, 0x62,
    0x65, 0x0a, 0x0a, 0x2d, 0x59, 0x20, 0x32, 0x20, 0x2b, 0x58, 0x20, 0x32, 0x0a, 0x00, 0x00, 0x00,
    0x00, 0x80, 0x00, 0x00, 0x81, 0x00, 0x80, 0x00, 0x81, 0x80, 0x80, 0x80, 0x83,
};

static void test_caps(void) {
    const zcsr_image_caps_info* caps = zcsr_image_caps();
    CK("caps non-null", caps != 0);
    CK("hdr supported", caps->decode[ZCSR_IMAGE_FMT_HDR]);
    CK("ico supported", caps->decode[ZCSR_IMAGE_FMT_ICO]);
    CK("cur supported", caps->decode[ZCSR_IMAGE_FMT_CUR]);
    CK("png supported", caps->decode[ZCSR_IMAGE_FMT_PNG]);
    CK("jpeg supported", caps->decode[ZCSR_IMAGE_FMT_JPEG]);
    CK("bmp supported", caps->decode[ZCSR_IMAGE_FMT_BMP]);
    CK("gif supported", caps->decode[ZCSR_IMAGE_FMT_GIF]);
    CK("webp supported", caps->decode[ZCSR_IMAGE_FMT_WEBP]);
    CK("animated true", caps->animated);
    CK("name hdr", strcmp(zcsr_image_format_name(ZCSR_IMAGE_FMT_HDR), "hdr") == 0);
    CK("name unknown", strcmp(zcsr_image_format_name((zcsr_image_format)999), "unknown") == 0);
}

static void test_detect(void) {
    static const unsigned char jpeg[] = { 0xFF, 0xD8, 0xFF, 0xE0, 0, 0 };
    static const unsigned char bmp[] = { 'B', 'M', 0, 0, 0, 0 };
    static const unsigned char gif[] = { 'G', 'I', 'F', '8', '9', 'a' };
    static const unsigned char webp[] = { 'R', 'I', 'F', 'F', 0, 0, 0, 0, 'W', 'E', 'B', 'P' };
    static const unsigned char ico[] = { 0, 0, 1, 0 };
    static const unsigned char cur[] = { 0, 0, 2, 0 };
    static const unsigned char garbage[] = { 0x01, 0x02, 0x03, 0x04 };

    CK("detect hdr", zcsr_image_detect_format(HDR_2x2, sizeof HDR_2x2) == ZCSR_IMAGE_FMT_HDR);
    CK("detect jpeg", zcsr_image_detect_format(jpeg, sizeof jpeg) == ZCSR_IMAGE_FMT_JPEG);
    CK("detect bmp", zcsr_image_detect_format(bmp, sizeof bmp) == ZCSR_IMAGE_FMT_BMP);
    CK("detect gif", zcsr_image_detect_format(gif, sizeof gif) == ZCSR_IMAGE_FMT_GIF);
    CK("detect webp", zcsr_image_detect_format(webp, sizeof webp) == ZCSR_IMAGE_FMT_WEBP);
    CK("detect ico", zcsr_image_detect_format(ico, sizeof ico) == ZCSR_IMAGE_FMT_ICO);
    CK("detect cur", zcsr_image_detect_format(cur, sizeof cur) == ZCSR_IMAGE_FMT_CUR);
    CK("detect unknown", zcsr_image_detect_format(garbage, sizeof garbage) == ZCSR_IMAGE_FMT_UNKNOWN);
    CK("detect null", zcsr_image_detect_format(0, 0) == ZCSR_IMAGE_FMT_UNKNOWN);
}

static void test_hdr_decode(void) {
    static unsigned char buffer[128 * 1024];
    zcsr_image img = zcsr_image_decode(HDR_2x2, sizeof HDR_2x2, buffer, sizeof buffer);
    int saw_black = 0, saw_red = 0, saw_green = 0, saw_bright = 0;
    int i;

    CK("hdr width", img.w == 2);
    CK("hdr height", img.h == 2);
    CK("hdr rgba", img.rgba != 0);
    if (!img.rgba) return;

    for (i = 0; i < 4; ++i) {
        int r = img.rgba[i * 4 + 0];
        int g = img.rgba[i * 4 + 1];
        int b = img.rgba[i * 4 + 2];
        if (r < 10 && g < 10 && b < 10) saw_black = 1;
        if (r > 100 && g < 60 && b < 60) saw_red = 1;
        if (g > 100 && r < 60 && b < 60) saw_green = 1;
        if (r > 150 && g > 150 && b > 150) saw_bright = 1;
    }
    CK("hdr black pixel", saw_black);
    CK("hdr red pixel tonemapped", saw_red);
    CK("hdr green pixel tonemapped", saw_green);
    CK("hdr highlight tonemapped bright", saw_bright);
}

static void test_hdr_guards(void) {
    static unsigned char buffer[128 * 1024];
    static unsigned char small[16];
    zcsr_image img;

    CK("hdr null invalid", zcsr_image_decode(0, 0, buffer, sizeof buffer).w == 0);
    CK("hdr null buffer invalid", zcsr_image_decode(HDR_2x2, sizeof HDR_2x2, 0, 0).rgba == 0);
    CK("hdr undersized buffer invalid",
       zcsr_image_decode(HDR_2x2, sizeof HDR_2x2, small, sizeof small).w == 0);

    /* Truncated HDR: header cut mid-way, before the resolution line. Must fail closed. */
    img = zcsr_image_decode(HDR_2x2, 20, buffer, sizeof buffer);
    CK("hdr truncated invalid", img.w == 0 && img.rgba == 0);
}

static void test_unsupported_fail_closed(void) {
    static unsigned char buffer[64 * 1024];
    /* Truncated WebP: header only, no bitstream. Must fail closed, not crash. */
    static const unsigned char webp[] = { 'R', 'I', 'F', 'F', 0, 0, 0, 0, 'W', 'E', 'B', 'P' };

    CK("truncated webp decode invalid", zcsr_image_decode(webp, sizeof webp, buffer, sizeof buffer).rgba == 0);
}

int main(void) {
    test_caps();
    test_detect();
    test_hdr_decode();
    test_hdr_guards();
    test_unsupported_fail_closed();
    if (!fails) printf("PASS: image hdr + caps + detect\n");
    return fails ? 1 : 0;
}
